scwin.submission1_callback = function() {
    mainGrid.setFocusedCell(0, 0, false);
    for (var i = 0; i < dlDgList.getRowCount(); i++) {
        if (dlDgList.getCellData(i, "spclCgoAuthCd").indexOf("Y") == 0) {
            mainGrid.setReadOnly("row", i, true);
        }
    }
};
