scwin.btnSave_onclick = function() {
    var rows = dlDgList.getModifiedIndex();
    dmSearchCondition.setJSON($p.parent().dmSearchCondition.getJSON());
    if (rows.length == 0) {
        common.alert(common.getMsg("COM00095"));
        return false;
    } else {
        var ref = [{
            id: "dmSearchCondition",
            key: "dmSearchCondition"
        }, {
            id: "dlDgList",
            key: "dlDgList"
        }]; //화면dm, 서버dm
        var target = [{
            id: "dlDgList",
            key: "dlDgList"
        }];
        promise = common.execute("managePartnerDgCargoApproval", "/USCG5000/managePartnerDgCargoApproval.do", ref, target, true, null);
        promise = promise.then(function(res) {
            mainGrid.setFocusedCell(0, 0, false);
        });
    }
}
scwin.checkMendatory = function() {
    var rhqCd = $p.parent().dmSearchCondition.get("rhqCd");
    var vslCd = $p.parent().dmSearchCondition.get("vslCd");
    var skdVoyNo = $p.parent().dmSearchCondition.get("skdVoyNo");
    var skdDirCd = $p.parent().dmSearchCondition.get("skdDirCd");
    // mendatory check
    if (!rhqCd) {
        common.alert(common.getMsg("COM00010", ["Value", "RHQ"]));
        return false;
    }
    if (!vslCd) {
        common.alert(common.getMsg("COM00010", ["Value", "Vessel"]));
        return false;
    }
    if (!skdVoyNo) {
        common.alert(common.getMsg("COM00010", ["Value", "Voyage"]));
        return false;
    }
    if (!skdDirCd) {
        common.alert(common.getMsg("COM00010", ["Value", "Direction"]));
        return false;
    }
    return true;
}
scwin.setContainerTypeSizeList = function() {
    var ref = [{
        id: "dmSearchCondition",
        key: "dmSearchCondition"
    }];
    var target = [{
        id: "dlCntrTpszList",
        key: "dlCntrTpszList"
    }];
    var promise = common.execute("searchCntrTpSzList", "/USCG5000/searchContainerTypeSizeList.do", ref, target, null, null);
    return promise;
}
scwin.addRow = function(e) {
    var rowCnt = dlDgList.getRowCount();
    if (scwin.checkMendatory()) {
        dlDgList.insertRow(rowCnt);
        mainGrid.setReadOnly("cell", rowCnt, mainGrid.getColumnID(1), false);
    }
};
scwin.copyRow = function(e) {
    //common.validateGridView("mainGrid");
    debugger;
    //Copy전 데이터 체크
    var chkIdx = mainGrid.getCheckedIndex("chk");
    for (var i = 0; i < chkIdx.length; i++) {
        var a = dlDgList.getCellData(chkIdx[i], 1);
        common.rowAdd("mainGrid", chkIdx[i] + i + 1);
    }
};
scwin.funcSearchMdmCode = function(rowIndex, colId, nowValue) {
    switch (colId) {
        case "cgoOprtrCd":
            var options = {
                "mdmKind": "CARRIER",
                "dataList": dlDgList,
                "grdView": mainGrid,
                "row": rowIndex,
                "codeColId": "cgoOprtrCd",
                "nameColId": null,
                "nextColId": "bkgRefNo",
                "notFoundMsgYn": "Y",
                "notFoundAfterPopupUseYn": "Y",
                "openPopup": "Y",
                "dataObj": {
                    "carrCd": nowValue
                }
            };
            bcm.mdmSearch(options);
            break;
        case "porCd":
        case "podCd":
            var options = {
                "mdmKind": "PORT",
                "dataList": dlDgList,
                "grdView": mainGrid,
                "row": rowIndex,
                "codeColId": "porCd",
                "nameColId": null,
                "nextColId": "polCd",
                "notFoundMsgYn": "Y",
                "notFoundAfterPopupUseYn": "Y",
                "openPopup": "Y",
                "dataObj": {
                    "locCd": nowValue,
                    "callPortFlg": "Y"
                }
            };
            bcm.mdmSearch(options);
            break;
        case "polCd":
            scwin.setPol(nowValue, rowIndex);
            break;
    }
};
scwin.getImdgInfo = function(rowIndex, colId, nowValue) {
    var data = {
        "unNo": nowValue
    };
    var options = {
        id: "UnNumberPop",
        popupName: "UN Number Inquiry",
        width: 1440,
        height: 420,
        dataObj: data
    };
    var promise = common.openPopup("/ui/container/vop/scg/imdgmanagement/imdgmaster/UISCG1101.xml", options);
    promise = promise.then(function(res) {
        var subsidiaryRisks = res.PARAM_DATA.imdgFstSbsdRiskCd;
        if (res.PARAM_DATA.imdgScndSbsdRiskCd != "")
            subsidiaryRisks += "/" + res.PARAM_DATA.imdgScndSbsdRiskCd;
        if (res.PARAM_DATA.imdgThrdSbsdRiskCd != "")
            subsidiaryRisks += "/" + res.PARAM_DATA.imdgThrdSbsdRiskCd;
        if (res.PARAM_DATA.imdgFrthSbsdRiskCd != "")
            subsidiaryRisks += "/" + res.PARAM_DATA.imdgFrthSbsdRiskCd;
        dlDgList.setCellData(rowIndex, "imdgUnNo", res.PARAM_DATA.imdgUnNo);
        dlDgList.setCellData(rowIndex, "imdgClssCd", res.PARAM_DATA.imdgClssCd);
        dlDgList.setCellData(rowIndex, "imdgSbsdRisks", subsidiaryRisks);
        dlDgList.setCellData(rowIndex, "mrnPolutFlg", (res.PARAM_DATA.imdgMrnPolutCd == 'P') ? 'Y' : 'N');
        dlDgList.setCellData(rowIndex, "imdgPkngGrpCd", res.PARAM_DATA.imdgPkngGrpCd);
        dlDgList.setCellData(rowIndex, "pkngGrpCd", res.PARAM_DATA.pkngGrpCd);
        dlDgList.setCellData(rowIndex, "imdgLmtQtyFlg", (res.PARAM_DATA.imdgLmtQty == '0') ? 'N' : 'Y');
        dlDgList.setCellData(rowIndex, "flsPntCesTemp", res.PARAM_DATA.flsPntTempCtnt);
        dlDgList.setCellData(rowIndex, "psaNo", res.PARAM_DATA.psaNo);
        dlDgList.setCellData(rowIndex, "psnNm", res.PARAM_DATA.psnNm);
    });
    return promise;
}
scwin.mainGrid_onviewchange = function(info) {
    var bkgNo = dlDgList.getCellData(info.rowIndex, "bkgRefNo");
    var cntrSeq = dlDgList.getCellData(info.rowIndex, "dctrSeq");
    //Container Type&Size 변경시 BKG, Container Seq 동일한것 모두 변경
    //row추가 데이터와 기존 저장 데이터의 BKG, Container Seq가 같은 경우를 위해
    if (info.colIndex == 9) { // Type/Size
        var cntrTpsz = dlDgList.getCellData(info.rowIndex, "prnrCntrTpszCd");
        for (var i = 0; i < dlDgList.getRowCount(); i++) {
            var tempBkgNo = dlDgList.getCellData(i, "bkgRefNo");
            var tempDctrSeq = dlDgList.getCellData(i, "cntrSeq");
            if ((tempBkgNo != "") &&
                (tempDctrSeq != "") &&
                (tempBkgNo.indexOf(bkgNo) > -1) &&
                (tempDctrSeq.indexOf(cntrSeq) > -1) &&
                (dlDgList.getCellData(i, "spclCgoAuthCd").indexOf("Y") == -1)) {
                dlDgList.setCellData(i, "prnrCntrTpszCd", cntrTpsz);
            }
        }
    }
    //Approval Status 변경시 BKG, Container Seq 동일한것 모두 변경
    //row추가 데이터와 기존 저장 데이터의 BKG, Container Seq가 같은 경우를 위해
    if (info.colIndex == 21) { // Approval
        var status = dlDgList.getCellData(info.rowIndex, "spclCgoAuthCd");
        for (var i = 0; i < dlDgList.getRowCount(); i++) {
            var tempBkgNo = dlDgList.getCellData(i, "bkgRefNo");
            var tempDctrSeq = dlDgList.getCellData(i, "cntrSeq");
            if ((tempBkgNo != "") &&
                (tempDctrSeq != "") &&
                (tempBkgNo.indexOf(bkgNo) > -1) &&
                (tempDctrSeq.indexOf(cntrSeq) > -1) &&
                (dlDgList.getCellData(i, "spclCgoAuthCd").indexOf("Y") == -1)) {
                dlDgList.setCellData(i, "spclCgoAuthCd", status);
            }
        }
    }
    //POL입력시
    if (info.colIndex == 4) { // POL
    }
};
scwin.setPol = function(polCd, row) {
    debugger;
    var options = {
        "mdmKind": "PORT",
        "dataList": dlDgList,
        "grdView": mainGrid,
        "row": row,
        "codeColId": "polCd",
        "nameColId": null,
        "nextColId": "eta",
        "notFoundMsgYn": "Y",
        "notFoundAfterPopupUseYn": "Y",
        "openPopup": "N",
        "returnPromise": "Y",
        "dataObj": {
            "locCd": polCd,
            "callPortFlg": "Y"
        }
    };
    var promise = bcm.mdmSearch(options);
    promise = promise.then(function(res) {
        var rtnData = bcm.getMdmRtnObj(res);
        var a = rtnData.locCd;
    });
}
scwin.setEta = function(row) {}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById('mainGrid_cell_7_9')).hasClass('w2grid_default_readonly')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
